$ErrorActionPreference='Stop'; $root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path; $module=Join-Path $root 'scripts\operator_proxy\Repair-OperatorProxy.psm1'; Import-Module $module -Force; $head=(git -C $root rev-parse HEAD).Trim(); $tmp=Join-Path $env:TEMP ('operator-proxy-'+[guid]::NewGuid()); New-Item $tmp -ItemType Directory|Out-Null
try {Invoke-OperatorProxyInstall -Repo $root -InstallRoot $tmp -ApprovedCommit $head|Out-Null; if(!(Test-Path (Join-Path $tmp 'operator_proxy.ts'))){throw 'install missing'}; try{Invoke-OperatorProxyInstall -Repo $root -InstallRoot $tmp -ApprovedCommit ('0'*40)|Out-Null;throw 'bad sha accepted'}catch{if($_.Exception.Message -eq 'bad sha accepted'){throw}}; 'OPERATOR_PROXY_TRANSACTION_PASS'} finally {Remove-Item $tmp -Recurse -Force}
